package device

import (
	"testing"

	"github.com/kubernetes-sigs/dra-driver-cpu/pkg/cpuinfo"
	"github.com/stretchr/testify/require"
)

func TestMakeSMTMap(t *testing.T) {
	testCases := []struct {
		name     string
		topo     *cpuinfo.CPUTopology
		expected string
	}{
		{
			name: "core i7 12850HX",
			topo: topoSingleCoreI712850HX,
		},
		{
			name:     "dual xeon gold 6320",
			topo:     topoDualXeonGold6320,
			expected: "0-79:40",
		},
		{
			name:     "dual xeon gold 6320 - variant",
			topo:     topoDualXeonGold6320Type2,
			expected: "0-79:40",
		},
		{
			name:     "dual epyc 7742",
			topo:     topoDualEpyc7742,
			expected: "0-255:128",
		},
		{
			name:     "dual epyc 9654",
			topo:     topoDualEpyc9654,
			expected: "0-383:192",
		},
		{
			name: "epyc 7702P",
			topo: topoSingleEpyc7702P,
		},
		{
			name: "dual epyc 7303",
			topo: topoDualEpyc7303,
		},
		{
			name:     "epyc 9754",
			topo:     topoSingleEpyc9754,
			expected: "0-255:128",
		},
		{
			name: "dual epyc 9654 - SNC",
			topo: topoDualEpyc9654SNC,
		},
		{
			name:     "dual xeon platinum 8490H",
			topo:     topoDualXeonPlatinum8490H,
			expected: "0-239:120",
		},
		{
			name: "knights landing",
			topo: topoOpenMPIKnightsLanding,
		},
	}
	for _, tcase := range testCases {
		t.Run(tcase.name, func(t *testing.T) {
			got := MakeSMTMap(tcase.topo)
			require.Equal(t, got, tcase.expected)
		})
	}
}

